import{_ as s,a as r,b as a,c as t}from"./chunks/Variant._HIU2fAQ.js";import{_ as i,o,c as n,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"Téléchargement","description":"","frontmatter":{"source_hash":"932cfecc51","source_commit":"298bb92"},"headers":[],"relativePath":"fr/install/download.md","filePath":"fr/install/download.md"}'),u={name:"fr/install/download.md"};function p(c,e,d,h,m,v){return o(),n("div",null,[...e[0]||(e[0]=[l('<h2 id="which-one-to-install" tabindex="-1">Laquelle installer ? <a class="header-anchor" href="#which-one-to-install" aria-label="Permalink to &quot;Laquelle installer ? {#which-one-to-install}&quot;">​</a></h2><p>xDrip n&#39;est pas disponible sur le Google Play Store. Vous trouverez toutes les versions sur <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">Github</a>.<br> Vous avez deux choix principaux pour installer xDrip : la <strong>dernière version stable</strong> (Latest release) ou une <strong>pré-version</strong> (Pre-release).</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Si xDrip est déjà installé sur votre téléphone, vous n&#39;avez pas besoin de le désinstaller avant d&#39;installer une mise à jour.<br> Si vous utilisez une version dérivée (fork) et voulez passer à une version officielle de xDrip, ou l&#39;inverse, suivez <a href="./../troubleshoot/reinstall.html">ceci</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Plusieurs installations de xDrip</p><p>Si vous devez installer plus d&#39;un xDrip sur le même téléphone, il vous faut une <a href="#variants">variante</a>.</p></div><h3 id="latest-release" tabindex="-1">Dernière version stable <a class="header-anchor" href="#latest-release" aria-label="Permalink to &quot;Dernière version stable {#latest-release}&quot;">​</a></h3><p>La dernière version stable (Latest release) est une version stable de xDrip. Elle n&#39;a pas toutes les fonctions les plus récentes, mais sa stabilité est éprouvée et elle ne souffre pas de bugs graves. C&#39;est une version sûre pour commencer, sauf si vous avez besoin d&#39;une fonction particulière (consultez le <a href="./../changelog.html">journal des modifications</a> pour le vérifier).</p><p>Vous pouvez la télécharger <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">ici</a> ou avec ce QR code :</p><img src="https://jamorham.github.io/images/download-xdrip-plus-qr-code-120.png"><p>Vous la trouverez aussi dans le <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">dépôt principal</a> en sélectionnant Latest.</p><img src="'+s+'" style="zoom:50%;"><br><h4 id="download-warning" tabindex="-1">Avertissement au téléchargement <a class="header-anchor" href="#download-warning" aria-label="Permalink to &quot;Avertissement au téléchargement {#download-warning}&quot;">​</a></h4><p>xDrip téléchargé depuis <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> est sûr.</p><img src="'+r+'" style="zoom:75%;"><br><p>Une fois le téléchargement terminé, <a href="./install.html">passez à l&#39;installation de xDrip</a></p><br><h3 id="pre-release" tabindex="-1">Pré-version <a class="header-anchor" href="#pre-release" aria-label="Permalink to &quot;Pré-version {#pre-release}&quot;">​</a></h3><p>Les pré-versions (Pre-release) contiennent les développements les plus récents de xDrip, comme les traductions, les nouvelles fonctions et les corrections de bugs. Elles peuvent aussi contenir quelques bugs... C&#39;est pourtant la version à utiliser pour profiter des dernières améliorations.</p><p>Toutes les versions de xDrip sont disponibles <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">ici</a>.</p><p>Dépliez les fichiers (Assets) et sélectionnez le fichier <code>.apk</code>. Vous le trouverez dans le dossier <code>Téléchargements</code> de votre téléphone.</p><img src="'+a+'" style="zoom:50%;"><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>N&#39;utilisez <strong>pas</strong> les liens Facebook pour télécharger xDrip, mais <strong>copiez et collez le lien</strong> dans un navigateur (comme Chrome).</p></div><br><h4 id="download-warning-1" tabindex="-1">Avertissement au téléchargement <a class="header-anchor" href="#download-warning-1" aria-label="Permalink to &quot;Avertissement au téléchargement {#download-warning-1}&quot;">​</a></h4><p>xDrip téléchargé depuis <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> est sûr.</p><img src="'+r+'" style="zoom:75%;"><br><p>Une fois le téléchargement terminé, <a href="./install.html">passez à l&#39;installation de xDrip</a></p><br><h2 id="forked-versions" tabindex="-1">Versions dérivées <a class="header-anchor" href="#forked-versions" aria-label="Permalink to &quot;Versions dérivées {#forked-versions}&quot;">​</a></h2><p>Certains développeurs ajoutent des fonctions et des personnalisations qui ne sont pas disponibles dans les pré-versions officielles, tant que leur auteur n&#39;a pas créé une Pull Request dans xDrip et qu&#39;elle n&#39;a pas été intégrée au projet principal.</p><div class="warning custom-block"><p class="custom-block-title">Mise à jour des versions dérivées</p><p>Vous pouvez utiliser ces versions, mais sachez qu&#39;elles ne sont parfois prises en charge que par leur créateur.<br><strong>Les mises à jour automatiques de xDrip ne fonctionnent pas avec les versions dérivées.</strong><br> Gardez aussi à l&#39;esprit que vous ne pouvez pas installer une version dérivée si une version officielle est installée sur votre téléphone :<br> vous devrez d&#39;abord la <a href="./../troubleshoot/reinstall.html">désinstaller</a>.<br> Il en va de même dans l&#39;autre sens (d&#39;une version dérivée vers une version officielle).</p></div><br><h2 id="variants" tabindex="-1">Variantes <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variantes {#variants}&quot;">​</a></h2><p>Quatre variantes sont publiées régulièrement, ce qui permet d&#39;installer jusqu&#39;à 5 xDrip sur votre téléphone. Cela peut être particulièrement utile pour suivre plusieurs personnes à la fois.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Il est déconseillé d&#39;utiliser une variante connectée à votre capteur : utilisez uniquement la version principale.<br> N&#39;utilisez les variantes que comme abonnés.<br> Certaines anciennes versions de xDrip laissaient fuir des valeurs avec AAPS/NSClient. Utilisez les dernières variantes.</p></div><p>Vous pouvez télécharger les variantes <a href="https://drive.google.com/drive/folders/0B6mvYVNVC-fOWkxnVF80dlFabjQ?resourcekey=0-ebguuiPuB1wUI9Rp2zjMNg" target="_blank" rel="noreferrer">ici</a>.</p><p>Triez-les par date de modification, les plus récentes en premier, et choisissez la variante à télécharger.</p><img src="'+t+'" style="zoom:90%;"><p>Les variantes sont aussi fournies comme fichiers (assets), à côté de l&#39;apk habituel, dans la dernière version stable sur <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><img src="'+s+'" style="zoom:50%;"><p>Une fois la variante téléchargée, procédez comme pour une installation normale de xDrip.</p><p><strong>Les variantes ne se mettent pas à jour automatiquement.</strong> Vous devez télécharger les mises à jour et les installer par-dessus la version actuelle de la variante (sans avoir besoin de la désinstaller) : veillez simplement à sélectionner la même variante (1 à 4).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Dernière modification le 3/2/2023</em></a></p>',46)])])}const x=i(u,[["render",p]]);export{f as __pageData,x as default};
